// Generated by Dataflare. Mount only on approved product/marketing pages.
(() => {
  if (document.currentScript?.dataset.enabled !== "true") return;
  const marketing = false;
  const allowed = () =>
    !/^\/(?:api|v1)(?:\/|$)/.test(location.pathname) &&
    (!marketing ||
      /^\/(?:$|teachers\/?$|leaders\/?$|families\/?$|developers(?:\/.*)?$|gadgets(?:\/.*)?$|connectors(?:\/.*)?$|pricing\/?$|privacy\/?$)/.test(
        location.pathname,
      ));
  if (!allowed()) return;
  if (
    window.doNotTrack === "1" ||
    navigator.doNotTrack === "1" ||
    navigator.globalPrivacyControl === true
  )
    return;
  const script = document.createElement("script");
  script.src = "https://observe.gmac.io/s.js";
  // No data-project: initialize explicitly below, before any event can be captured.
  script.addEventListener("load", () => {
    if (!window.glass || typeof window.glass.init !== "function") return;
    window.glass.init({
      host: "https://observe.gmac.io",
      project: "bob",
      persistence: "localStorage",
      autocapture: {
        pageviews: true,
        clicks: false,
        errors: false,
        webVitals: false,
      },
      flags: false,
      replay: false,
      beforeSend: (event) => {
        if (!allowed() || event.event !== "$pageview") return null;
        // Fixed screen categories avoid sending entity ids, search text, document titles or query parameters.
        const first = location.pathname.split("/").filter(Boolean)[0] || "home";
        const screens = [
          "home",
          "capture",
          "conversations",
          "oracle",
          "research",
          "threads",
          "health",
        ];
        const screen = screens.includes(first) ? first : "other";
        return {
          ...event,
          url: location.origin + "/" + screen,
          title: null,
          referrer: null,
          props: {},
          flags: undefined,
        };
      },
    });
  });
  document.head.append(script);
})();
